-- Dev-only catalog rows for Sushi Shift on the LAN (entry served by pnpm --filter @rally/game-sushi dev on :5185,
-- strictPort). Generated from `publish-game sushi --dry-run` (publish-plan.json): the games row, the manifest, the
-- `days` / `tips` (best) boards and the five achievements; art is left out (the dry run's CDN URLs are placeholders;
-- a real publish uploads it). Replace 10.0.0.201 with the PC LAN IP. Re-runnable. The game server must be v5 (the
-- `sushi` room). A real publish adds 0.1.0 next to this -dev version and repoints current_version_id.
insert into public.games (id,title,description,genres,screenshots,icon_url,cover_url,engine,orientation,min_players,max_players,modes,age_rating,min_app_version,status)
values ('sushi','Sushi Shift','Run a tiny conveyor-belt sushi bar with up to three friends, one week of shifts at a time. Chop fish, cook rice, roll nigiri and maki, and set the plates on the kaiten belt: the customers on the stools grab what they ordered as it rides past. From Wednesday the dining room opens for ramen, udon, gyoza and steamed buns carried to the tables, then come the dirty dishes, a picky VIP, the fish truck and Sunday''s festival rush. Every night the crew votes on an upgrade. Keep the stars, survive the week, then see how far Overtime goes. The boards keep your best day reached and your best day of tips.',array['cooking','co-op','casual']::text[],'{}'::text[],null,null,'playcanvas','landscape',1,4,array['quick','browser','private']::public.game_mode[],'4+','0.0.0','published')
on conflict (id) do update set title=excluded.title, description=excluded.description, genres=excluded.genres, min_players=excluded.min_players, max_players=excluded.max_players, modes=excluded.modes, age_rating=excluded.age_rating, status='published';

insert into public.game_versions (game_id,version,entry_url,manifest,sha256,size_bytes)
