on conflict (game_id,version) do update set entry_url=excluded.entry_url, manifest=excluded.manifest;

update public.games set current_version_id=(select id from public.game_versions where game_id='sushi' and version='0.1.0-dev') where id='sushi';

insert into public.leaderboards (game_id,key,sort,period,max_score_per_minute,mode) values ('sushi','days','desc','alltime',null,'best') on conflict (game_id,key) do update set mode=excluded.mode;
insert into public.leaderboards (game_id,key,sort,period,max_score_per_minute,mode) values ('sushi','tips','desc','alltime',null,'best') on conflict (game_id,key) do update set mode=excluded.mode;
insert into public.achievements (game_id,key,title,description,icon,hidden) values ('sushi','survive_week','Survive the Week','Keep the restaurant open through Sunday''s festival rush.','🎏',false) on conflict (game_id,key) do nothing;
